{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-o7cCD4/src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph from the raw text read on standard input.
 *
 * Returns `{ tasks, depMap }`, where `tasks` maps a task name to its cost
 * and `depMap` maps a task name to the `Set` of names it directly depends
 * on. Every name that appears in `depMap` (as a key or in a value set) is
 * guaranteed to be a key of `tasks`.
 */
export function parseGraph(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const tasks = new Map()
  const depLines = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(2, `error: line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(2, `error: line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(2, `error: line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(2, `error: line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(2, `error: line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const deps = words.slice(2)
      for (const n of [name, ...deps]) {
        if (!NAME_RE.test(n)) {
          throw new CliError(2, `error: line ${lineNo}: invalid task name ${n}`)
        }
      }
      depLines.push({ name, deps })
    } else {
      throw new CliError(2, `error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const { name, deps } of depLines) {
    for (const n of [name, ...deps]) {
      if (!tasks.has(n)) {
        throw new CliError(2, `error: unknown task ${n}`)
      }
    }
  }

  const depMap = new Map()
  for (const name of tasks.keys()) depMap.set(name, new Set())
  for (const { name, deps } of depLines) {
    const set = depMap.get(name)
    for (const d of deps) set.add(d)
  }

  return { tasks, depMap }
}
"}

