/**
 * Finds the first cycle a depth-first search discovers, starting from each
 * task in ascending name order and walking each task's dependencies in
 * ascending name order. Returns the cycle as an array of names running from
 * the re-entered task, through the search stack, back to that task, or
 * `null` when the graph is acyclic.
 */
export function detectCycle(tasks, depMap) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function visit(u) {
    visited.add(u)
    onStack.add(u)
    stack.push(u)

    const deps = [...depMap.get(u)].sort()
    for (const v of deps) {
      if (onStack.has(v)) {
        const idx = stack.indexOf(v)
        return stack.slice(idx).concat(v)
      }
      if (!visited.has(v)) {
        const found = visit(v)
        if (found) return found
      }
    }

    stack.pop()
    onStack.delete(u)
    return null
  }

  for (const name of names) {
    if (!visited.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/** Raises the cycle error for the given cycle path. */
export function cycleError(cycle) {
  return new CliError(3, `error: cycle: ${cycle.join(' -> ')}`)
}

/**
 * Computes each task's wave: 0 for a task with no dependency, otherwise one
 * more than the deepest wave among its dependencies. Assumes the graph is
 * acyclic.
 */
export function computeDepths(tasks, depMap) {
  const depth = new Map()

  function calc(u) {
    if (depth.has(u)) return depth.get(u)
    const deps = depMap.get(u)
    let d = 0
    for (const v of deps) d = Math.max(d, calc(v) + 1)
    depth.set(u, d)
    return d
  }

  for (const name of tasks.keys()) calc(name)
  return depth
}

/**
 * Computes each task's start and finish time with unlimited workers: start
 * is the greatest finish among its dependencies (0 when it has none), and
 * finish is start plus cost. Assumes the graph is acyclic.
 */
export function computeTimes(tasks, depMap) {
  const start = new Map()
  const finish = new Map()

  function calc(u) {
    if (finish.has(u)) return finish.get(u)
    const deps = depMap.get(u)
    let s = 0
    for (const v of deps) s = Math.max(s, calc(v))
    const f = s + tasks.get(u)
    start.set(u, s)
    finish.set(u, f)
    return f
  }

  for (const name of tasks.keys()) calc(name)
  return { start, finish }
}

/**
 * Computes each task's priority for packing: the cost of the longest chain
 * of dependents that begins at it, counting its own cost and then the
 * costs down to any task that nothing depends on. Assumes the graph is
 * acyclic.
 */
export function computePriorities(tasks, depMap) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of depMap) {
    for (const d of deps) dependents.get(d).push(name)
  }

  const priority = new Map()

  function calc(u) {
    if (priority.has(u)) return priority.get(u)
    const ds = dependents.get(u)
    let best = 0
    for (const d of ds) best = Math.max(best, calc(d))
    const p = tasks.get(u) + best
    priority.set(u, p)
    return p
  }

  for (const name of tasks.keys()) calc(name)
  return priority
}
"}

