  const priority = computePriorities(tasks, depMap)

  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, deps] of depMap) {
    for (const d of deps) dependents.get(d).push(name)
  }

  const remaining = new Map()
  for (const name of names) remaining.set(name, depMap.get(name).size)

  const readySet = new Set(names.filter((n) => remaining.get(n) === 0))
  const pendingFinishes = [] // { name, finish }, for cost > 0 tasks not yet applied

  const workerFreeAt = new Array(workerCount).fill(0)
  let doneCount = 0
  let currentTime = 0

