    for (const dep of dependents.get(name)) {
      const rem = remaining.get(dep) - 1
      remaining.set(dep, rem)
      if (rem === 0) readySet.add(dep)
    }
  }

  function pickBest() {
    let best = null
    for (const n of readySet) {
      if (best === null) continue
      const pn = priority.get(n)
      const pb = priority.get(best)
      if (pn > pb || (pn === pb && n < best)) best = n
    }
    if (best === null) best = readySet.values().next().value
    return best
  }

  while (doneCount < names.length) {
    for (;;) {
      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1 || readySet.size === 0) break

      const name = pickBest()
      readySet.delete(name)
      const cost = tasks.get(name)
      const finish = currentTime + cost
      workerFreeAt[freeWorker] = finish
      workerRuns[freeWorker].push({ name, start: currentTime, finish })
      doneCount++

      if (cost === 0) {
        applyFinish(name)
      } else {
        pendingFinishes.push({ name, finish })
      }
    }

    if (doneCount === names.length) break

    let nextTime = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > currentTime) nextTime = Math.min(nextTime, workerFreeAt[i])
    }
    currentTime = nextTime

    for (let i = pendingFinishes.length - 1; i >= 0; i--) {
