{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-o7cCD4/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import fs from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { detectCycle, cycleError, computeDepths, computeTimes } from './graph.js'
import { packSchedule } from './schedule.js'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError(2, 'error: workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(2, 'error: usage: cli.js waves|explain|pack <workers>')
}

function runWaves(tasks, depMap) {
  const depth = computeDepths(tasks, depMap)
  const { finish } = computeTimes(tasks, depMap)

  let maxDepth = -1
  for (const d of depth.values()) maxDepth = Math.max(maxDepth, d)

  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const names = [...tasks.keys()].filter((n) => depth.get(n) === k).sort()
    lines.push(`wave ${k}: ${names.join(' ')}`)
  }

  let total = 0
  for (const f of finish.values()) total = Math.max(total, f)
  lines.push(`total ${total}`)

  return lines.join('\n') + (lines.length > 0 ? '\n' : '')
}

function runExplain(tasks, depMap) {
  const depth = computeDepths(tasks, depMap)
  const { start, finish } = computeTimes(tasks, depMap)

  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }

  let total = 0
  for (const f of finish.values()) total = Math.max(total, f)
  lines.push(`total ${total}`)

  return lines.join('\n') + '\n'
}

function runPack(tasks, depMap, workers) {
  const { workerRuns, makespan } = packSchedule(tasks, depMap, workers)

  const lines = workerRuns.map((run, i) => {
    const body = run.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
    return `worker ${i}:${body}`
  })
  lines.push(`makespan ${makespan}`)

  return lines.join('\n') + '\n'
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = fs.readFileSync(0, 'utf8')
  const { tasks, depMap } = parseGraph(input)

  const cycle = detectCycle(tasks, depMap)
  if (cycle) throw cycleError(cycle)

  if (mode === 'waves') {
    process.stdout.write(runWaves(tasks, depMap))
  } else if (mode === 'explain') {
    process.stdout.write(runExplain(tasks, depMap))
  } else {
    process.stdout.write(runPack(tasks, depMap, workers))
  }
}

try {
  main()
} catch (err) {
